381	/**
382	 * Atomic spawn admission (audit P-017 + P-039, EI-73): reclaim → idempotency
383	 * dedupe → cap count → record, in ONE transaction serialized per workspace by
384	 * an advisory xact lock. Closes two races the old
385	 * reclaim-then-count-then-insert sequence had under read-committed:
386	 *   • two concurrent spawns both read running<cap and both recorded
387	 *     (ceiling overshoot, P-039);
388	 *   • a route-timeout retry of the SAME logical spawn launched a second agent
389	 *     (EI-73) — a caller-supplied idempotencyKey now returns the original row
390	 *     instead. The partial unique index from migration 219 backstops the
391	 *     dedupe even outside this lock.
392	 *
393	 * `record` runs inside the transaction only when admission succeeds; it must
394	 * use the handed tx. Exported for the real-PG concurrency tests.
395	 */
396	export async function admitSpawn(
397	  sql: Sql,
398	  opts: {
399	    workspaceId: string;
400	    /** The spawn id `record` inserts — the idempotency key is stamped on it. */
401	    spawnId: string;
402	    idempotencyKey: string | null;
403	    cap: number;
404	    record: (tx: Db) => Promise<void>;
405	  },
406	): Promise<{ admission: SpawnAdmission; reclaimed: { count: number; workspaces: string[] } }> {
407	  let reclaimed = { count: 0, workspaces: [] as string[] };
408	  const admission = (await sql.begin(async (tx): Promise<SpawnAdmission> => {
409	    await tx`SELECT pg_advisory_xact_lock(hashtext(${`opspawn:${opts.workspaceId}`}))`;
410	
411	    // Reclaim orphaned rows (a host that died mid-spawn left 'running' rows
412	    // that never flip) BEFORE counting, so the ceiling reflects live spawns
413	    // only and a dead host's rows can never wedge it (P-011). Announce is the
414	    // caller's job, AFTER commit.
415	    const r = await reclaimOrphanedSpawns(tx);
416	    reclaimed = { count: r.reclaimed, workspaces: r.workspaces };
417	
418	    if (opts.idempotencyKey) {
419	      const dup = await tx<{ spawn_id: string }[]>`
420	        SELECT spawn_id FROM harness_shared.spawned_agents
421	         WHERE workspace_id = ${opts.workspaceId} AND idempotency_key = ${opts.idempotencyKey}
422	         LIMIT 1`;
423	      if (dup.length > 0) return { kind: 'duplicate', spawnId: dup[0].spawn_id };
424	    }
425	
426	    const running = await countRunning(opts.workspaceId, tx);
427	    if (running >= opts.cap) return { kind: 'over_cap', running, cap: opts.cap };
428	
429	    await opts.record(tx);
430	    if (opts.idempotencyKey) {
431	      // Separate UPDATE so the recordSpawn input type stays untouched; same
432	      // transaction, so the key is never observable without the row.
433	      await tx`UPDATE harness_shared.spawned_agents
434	                  SET idempotency_key = ${opts.idempotencyKey}
435	                WHERE spawn_id = ${opts.spawnId}`;
436	    }
437	    return { kind: 'admitted' };
438	  })) as SpawnAdmission;
439	  return { admission, reclaimed };
440	}
