305	export interface OperatorSpawnInput {
306	  workspaceId: string;
307	  /** Registry slug of the harness to spawn into. Optional ONLY when the
308	   *  workspace has exactly one registered harness (it becomes the default). */
309	  harness?: string | null;
310	  /** Child agent role (AGENT_ROLES or a plugin-namespaced role). */
311	  role: string;
312	  featureId?: string | null;
313	  chunkId?: string | null;
314	  /** Queen-authored brief: the situational overlay the bee is MISSING. P-060. */
315	  brief?: string | null;
316	  /**
317	   * Per-spawn model escalation (queen-model-tier-selection-2026-06-11).
318	   * `tier` names an entry in the user-defined tier menu (AgentConfig.tiers,
319	   * default quick/standard/deep/max) — resolved + clamped to [role floor,
320	   * role ceiling] by resolveTierSpec. `modelSpec` is a direct
